/*saveOrderChangeCombineLogic_modifyICOMPOHD*/
UPDATE ICOMPOHD PH SET STATUS = DECODE((SELECT NVL(COUNT(*),0) FROM ICOMPODT WHERE BUYER = PH.BUYER AND PO_NO = PH.PO_NO AND STATUS != 'D'), 0, 'D','R'),
PO_TTL_AMT = (SELECT NVL(SUM(PD.ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), PO_TAX_TTL_AMT = (SELECT NVL(SUM(PD.ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), AGENT_PO_TTL_AMT = (SELECT NVL(SUM(PD.AGENT_ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), SEND_DATE = ' ', SEND_TIME = ' ', --수주접수 무관 이고 수량변경의 경우 (변경코드 중 수량변경코드가 포함된 경우 ) COMPLETE_MARK = NVL((SELECT DECODE(MIN(NVL(COMPLETE_MARK, 'N')), MAX(NVL(COMPLETE_MARK, 'N')), MIN(NVL(COMPLETE_MARK, 'N')) , 'N') FROM ICOMPODT WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO} AND STATUS != 'D' ),'N'),
DOC_TYPE = #{DOC_TYPE} , -- 긴급여부 DS_FLAG = #{DS_FLAG} , -- 거래명세서를 분할하여 생성할수 있는지에 대한 값
CHANGE_USER_ID = #{st_po_change_user_id}, CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS') WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO}

/*saveOrderChangeCombineLogic_modifyICOMPRHD*/

      UPDATE ICOMPRHD 
         SET STATUS = DECODE((SELECT COUNT(*) 
                                FROM ICOMPRDT 
                               WHERE BUYER = #{BUYER}  
                                 AND PR_NO = #{PR_NO}  
                                 AND STATUS IN ('C','R')),0,'D','R'),  
             DOC_TYPE = #{DOC_TYPE}  -- 긴급여부                      
       WHERE BUYER = #{BUYER}                                      
         AND PR_NO = #{PR_NO}


				 /*registerICOMPODT_DOCU*/

  INSERT INTO ICOMPODT_DOCU (   
						DOCU_NO
						,COMPANY
						,BUYER
						,PR_NO
						,PR_SEQ
						,PO_NO
						,PO_SEQ
						,PROCESS_TYPE
						,AGENT
						,UNIT_PRICE
						,AGENT_PRICE
						,KEP_PRICE
						,ITEM_QTY
						,DOC_TYPE
						,DS_FLAG
						,CLSD_FLAG
						,PO_CHANGE_USER_ID
						,WAREHOUSE_CODE
						,BUDGET_FLAG
						,RS_FLAG
						,HIST_RSN_CD
						,HIST_ID
						,CMS_CATLG_ID
						,CA_FLAG
						,PROC_USER_ID
						,PROC_DATE
						,PROC_TIME     
						,IMPORT_FLAG     
						,PASS_STATUS
						,EXP_CUR
						,EXP_CUR_PRICE
						,EXP_GR_NO
						,EXP_DATE_OF_SHIPMENT
						,CA_EXCEPT_REASON
                        ) VALUES (                 
						#{DOCU_NO}
						,#{COMPANY}
						,#{BUYER}
						,#{PR_NO}
						,#{PR_SEQ}
						,#{PO_NO}
						,#{PO_SEQ}
						,#{PROCESS_TYPE}
						,#{AGENT}
						,#{UNIT_PRICE}
						,#{AGENT_PRICE}
						,#{KEP_PRICE}
						,#{ITEM_QTY}
						,#{DOC_TYPE}
						,#{DS_FLAG}
						,#{CLSD_FLAG}
						,#{PO_CHANGE_USER_ID}
						,#{WAREHOUSE_CODE}
						,#{BUDGET_FLAG}
						,#{RS_FLAG}
						,#{HIST_RSN_CD}
						,#{HIST_ID}
						,#{CMS_CATLG_ID}
						,DECODE(#{REASON6},'0','N','Y')
						,#{PROC_USER_ID}
						,TO_CHAR(SYSDATE, 'YYYYMMDD')
						,TO_CHAR(SYSDATE, 'HH24MISS')
						,#{IMPORT_FLAG}
						,'0' -- 결재상태(0:진행중,1:반려,2:참조진행중,3:결재완료,4:상신취소)
						,#{DOCU_EXP_CUR}
						,#{DOCU_EXP_CUR_PRICE}
						,#{DOCU_EXP_GR_NO}
						,#{DOCU_EXP_DATE_OF_SHIPMENT}
						,#{CA_EXCEPT_REASON}
                )


 /*modify_ICOMPODT_DOCU_PASSSTATUS*/ 

	UPDATE ICOMPODT_DOCU
	SET PASS_STATUS = #{PASS_STATUS}
	WHERE 
	(DOCU_NO,COMPANY) IN (SELECT KEY_1,COM_CODE FROM ICOMTRGW WHERE COM_CODE = #{COMPANY} AND TARGET = #{DOCU_NO} AND  DOC_NAME = #{DOCU_TYPE} )


			/*modifyApprovalCa_flag5*/
			   UPDATE KEP_CURRENCY_DT A  
			   SET A.EXP_FOR_UNIT_PRICE = F_GET_EXCHANGE_RATE(#{BUYER}, #{UNIT_PRICE}, A.EXP_CODE, '01') ,
			              A.EXP_KR_UNIT_PRICE = F_GET_EXCHANGE_RATE(#{BUYER}, #{UNIT_PRICE}, A.EXP_CODE, '03') ,
			              A.EXP_INC_EXPENSE = F_GET_EXCHANGE_RATE(#{BUYER}, #{UNIT_PRICE}, A.EXP_CODE, '02') ,
			              A.CHANGE_USER_ID = #{st_po_change_user_id} ,
			              A.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') ,                                            
			              A.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
               WHERE A.BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY  WHERE COM_CODE = #{BUYER})   
               AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
               AND A.CONTRACT_NO = #{CONTRACT_NO}
               AND A.CONTRACT_SEQ =#{CONTRACT_SEQ}

